<template>
  <DefaultLayout>
    <v-container :class="IS_CART_EMPTY ? 'v-col-lg-5 v-col-md-6 v-col-sm-12' : 'col-12'" fluid>
      <v-row>
        <v-col cols="12">
          <h2 class="text-center" v-if="!IS_CART_EMPTY">{{ cart_title }}</h2>
          <p class="text font-light text-center pb-3 opacity-80" v-if="!IS_CART_EMPTY">{{ cart_desc }}</p>
          <v-sheet elevation="0">
            <template v-if="!IS_CART_EMPTY">
              <v-sheet>
                <v-expand-transition v-if="show_checkout">
                  <v-sheet v-if="model != null" class="pb-6">
                    <v-col class="pt-2 pb-2 pl-1 pr-0">
                      <v-btn class="pa-0" variant="plain" @click="this.goBack">
                        <v-icon left>mdi-arrow-left</v-icon>
                        Go back
                      </v-btn>
                    </v-col>
                    <div class="d-flex fill-height align-center justify-center">
                      <RedirectWidget v-if="model===0" :images="CART_LIST" :amount="this.vxCartTotalPrice"></RedirectWidget>
                      <EmbedCart v-if="model===3" :amount="this.vxCartTotalPrice"></EmbedCart>
                      <MobileWidget v-if="model===1" :amount="this.vxCartTotalPrice"></MobileWidget>
                      <CheckoutJsWidget v-if="model===2" :amount="this.vxCartTotalPrice"></CheckoutJsWidget>
                      <SimpleCardWidget v-if="model===4" :amount="this.vxCartTotalPrice"></SimpleCardWidget>
                      <PlainCardWidget v-if="model===5" :amount="this.vxCartTotalPrice"></PlainCardWidget>
                    </div>
                  </v-sheet>
                </v-expand-transition>
                <v-container class="pa-4" v-if="!show_checkout">
                  <v-row>
                    <v-col v-for="n in checkouts" :key="n" cols="12" lg="4" md="6" sm="6">
                      <v-card
                          class="ma-md-4"
                          height="390"
                          elevation="1"
                          @click="handleClick(n)"
                      >
                        <div class="d-flex flex-column pa-md-5">
                          <v-img height="200" :src="n.image"></v-img>
                          <h4 class="text-center mt-2 mb-5">{{ n.name }}</h4>
                          <span class="text-center pa-1 small">{{ n.description }}</span>
                        </div>
                      </v-card>
                    </v-col>
                  </v-row>
                </v-container>
              </v-sheet>
            </template>
            <template v-else>
              <section class="cart-empty-container ">
                <div class="message-wrapper">
                  <h4 class="font-bold text-h6 py-3">{{ CONTENT.cartEmpty.title }}</h4>
                  <p class="font-thin">{{ CONTENT.cartEmpty.message }}</p>
                  <v-btn
                      :text="CONTENT.buttonText.shopNow"
                      variant="flat"
                      :color="colors.primary"
                      size="large"
                      class="my-5"
                      @click="goToHomepage">
                  </v-btn>
                </div>
                <div class="image-wrapper">
                  <img src="https://flitt.com/wp-content/uploads/2024/09/Group-67113.png"
                       alt="guy holding a shopping cart" width="300"
                       height="400">
                </div>
              </section>
            </template>
          </v-sheet>
        </v-col>
      </v-row>
    </v-container>
  </DefaultLayout>
</template>

<script>
import DefaultLayout from "@/layouts/DefaultLayout.vue";

import EmbedCart from "@/components/widgets/EmbedCart.vue";
import RedirectWidget from "@/components/widgets/Redirect.vue";
import MobileWidget from "@/components/widgets/Mobile.vue";
import CheckoutJsWidget from "@/components/widgets/CheckoutJs.vue";
import PlainCardWidget from "@/components/widgets/PlainCardWidget.vue";

import STATIC_CONTENT from "@/static/content.json";
import colors from "@/utils/colors.js";

import checkout_redirect from "@/assets/images/checkout_redirect.png";
import embed_checkout from "@/assets/images/embed_checkout.png";
import mobile_checkout from "@/assets/images/mobile_checkout.png";
import widget_checkout from "@/assets/images/widget_checkout.png";
import simple_widget from "@/assets/images/simple_widget.png";
import plain_widget from "@/assets/images/palin_checkout.png";

import {createNamespacedHelpers as nameSpace} from "vuex";
import SimpleCardWidget from "@/components/widgets/SimpleCardWidget.vue";


const {
  mapGetters: cartGetters,
  mapActions: cartActions,
} = nameSpace("cartModule");

export default {
  name: "Cart",
  components: {
    SimpleCardWidget,
    RedirectWidget,
    MobileWidget,
    CheckoutJsWidget,
    PlainCardWidget,
    EmbedCart,
    DefaultLayout,
  },
  data() {
    return {
      cart_title: "",
      cart_title_default: "Shopping Cart",
      cart_desc: "",
      cart_desc_default: "Choose any integration method and see how it works with Flitt",
      colors: colors,
      checkouts: [
        {
          'name': 'Redirect checkout',
          'description': 'You can use the Redirect integration type if you are fine with redirecting customer from your site to payment page hosted on Flitt side.',
          'image': checkout_redirect,
          'number': 0
        },
        {
          'name': 'Mobile checkout',
          'description': 'Easily integrate Flitt payments into your mobile app with our iOS, Android, React Native and Flutter SDKs or use an adaptive mobile & tablet web solution for a seamless checkout experience.',
          'image': mobile_checkout,
          'number': 1
        },
        {
          'name': 'Simple Checkout Widget',
          'description': 'Integrate seamlessly into any element of your web page, whether you\'re using a builder or not - quick and effortless.',
          'image': widget_checkout,
          'number': 2
        },
        {
          'name': 'Embedded checkout',
          'description': 'Create a customizable payment form with minimal code and embed it on your site or host it with Flitt.',
          'image': embed_checkout,
          'number': 3
        },
        {
          'name': 'Advanced customizable checkout',
          'description': 'Tailor Checkout’s colors, fonts, shapes, and branding to seamlessly match your site’s design.',
          'image': simple_widget,
          'number': 4
        },
        {
          'name': 'Plain checkout',
          'description': 'Tailor Checkout’s colors, fonts, shapes, and branding to seamlessly match your site’s design.',
          'image': plain_widget,
          'number': 5
        }
      ]
    };
  },
  computed: {
    ...cartGetters({
      vxCart: "cart",
      vxCartTotalPrice: "totalPrice",
      model: "model",
      show_checkout: "show_checkout"
    }),
    CART_LIST() {
      return JSON.parse(JSON.stringify(this.vxCart));
    },
    IS_CART_EMPTY() {
      return this.CART_LIST?.length === 0;
    },
    CONTENT() {
      return STATIC_CONTENT;
    },
  },
  methods: {
    ...cartActions([
      "updateCartVuex",
      "removeFromCartVuex",
      "clearCartVuex",
      "setCheckout",
      "addToCartVuex",
      "setView",
    ]),
    handleClick(n) {
      this.setCheckout(n.number);
      this.setView(!this.show_checkout);
      this.setDesc()
    },
    goToHomepage() {
      this.$router.push('/');
    },
    goBack() {
      this.setView(false);
      this.setDesc()
    },
    setDesc() {
      let current_name = this.cart_title_default
      let current_description = this.cart_desc_default
      if (this.show_checkout) {
        const current = this.checkouts.find(item => item.number === this.model);
        current_name = current.name
        current_description = current.description
      }
      this.cart_desc = current_description
      this.cart_title = current_name
    }
  },
  beforeMount() {
    this.setDesc()
  },
  mounted() {
    if (this.$route.query.checkout) {
      let test_cart = {
        id: 1,
        title: 'Demo product',
        price: 100,
        image: 'https://flitt.com/wp-content/uploads/2024/11/4n7.png',
        quantity: 5,
      };
      this.addToCartVuex(test_cart);
      this.setCheckout(parseInt(this.$route.query.checkout, 10) || 3);
      this.setView(true);
      this.$router.push('/cart');
    }
  },
  beforeRouteLeave(to, from, next) {
    if (this.show_checkout && to.name !== 'payment') {
      this.setView(false);
      this.setDesc()
      return next(false);
    }
    return next();
  },
};
</script>

<style lang="scss" scoped>
.small {
  font-size: 0.9rem;
}
.cart-item {
  display: flex;
  justify-content: space-between;
  max-width: 320px;

  .cart-name {
    grid-column: 2 / 3;
    display: flex;
    flex-direction: column;
    padding: 0 1rem;

    span:nth-child(1) {
      font-size: 1.25rem;
    }
  }

  .cart-delete {
    grid-column: 3 / 4;
    grid-row: 1 / 3;
    padding-top: 1.75rem;
  }

  .qty-wrapper {
    grid-column: 4 / 5;
  }
}

.big {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  font-size: 1.25rem;
  padding: 1rem;

  span {
    font-size: 1.25rem;
    padding-right: 1.5rem;
  }
}

.cart-empty-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.5rem;
}

@media (max-width: 580px) {
  .cart-empty-container {
    text-align: center;
    flex-direction: column;
  }
}
</style>
